package ems.controller;

import ems.dto.*; import ems.model.*; import ems.repository.*; import ems.service.*; import service.GroupChatService;
import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid;
import org.springframework.beans.factory.annotation.Value; import org.springframework.core.io.InputStreamResource; import org.springframework.http.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.server.ResponseStatusException;
import java.io.*; import java.math.BigDecimal; import java.nio.file.*; import java.time.LocalDate; import java.util.*; import java.util.stream.Collectors;

@RestController @RequestMapping("/api/ems")
public class EmsController {
    private final EmsAccessService access; private final EmsAgentService agents; private final service.WorkspaceAgentService workspaceAgents; private final EmployeeRepository employees; private final DepartmentRepository departments; private final ProjectRepository projects; private final ProjectMemberRepository members; private final AttendanceRepository attendance; private final LeaveRequestRepository leaves; private final SalaryRecordRepository payroll; private final EmployeeDocumentRepository documents; private final PerformanceReviewRepository reviews; private final AnnouncementRepository announcements; private final EmsNotificationService notifications; private final GroupChatService chatGroups; private final SystemSettingRepository settings;
    @Value("${ems.files.directory:${java.io.tmpdir}/teamconnect-ems-files}") private String fileDirectory;
    public EmsController(EmsAccessService a,EmsAgentService agents,service.WorkspaceAgentService workspaceAgents,EmployeeRepository e,DepartmentRepository d,ProjectRepository p,ProjectMemberRepository m,AttendanceRepository at,LeaveRequestRepository l,SalaryRecordRepository s,EmployeeDocumentRepository doc,PerformanceReviewRepository r,AnnouncementRepository an,EmsNotificationService n,GroupChatService g,SystemSettingRepository ss){access=a;this.agents=agents;this.workspaceAgents=workspaceAgents;employees=e;departments=d;projects=p;members=m;attendance=at;leaves=l;payroll=s;documents=doc;reviews=r;announcements=an;notifications=n;chatGroups=g;settings=ss;}

    @GetMapping("/employees") public Object employeeList(HttpServletRequest r){access.requireHrOrAdmin(r);return employees.findAllByOrderByNameAsc();}
    @GetMapping("/employees/me") public Employee employeeMe(HttpServletRequest r){return access.currentEmployee(r);}
    @GetMapping("/employees/{id}") public Employee employee(@PathVariable Long id,HttpServletRequest r){return access.requireEmployee(r,id);}
    @PostMapping("/employees") public Employee createEmployee(@Valid @RequestBody EmployeeRequest x,HttpServletRequest r){access.requireHrOrAdmin(r);requireChoice(x.status(),"ACTIVE","INACTIVE");requireChoice(x.role(),"ADMIN","HR","MANAGER","EMPLOYEE");Employee e=employeeFrom(x);if(!access.admin(r))e.setRole("EMPLOYEE");Employee saved=employees.save(e);agents.notifyOnboarding(saved);return saved;}
    @PutMapping("/employees/{id}") public Employee updateEmployee(@PathVariable Long id,@Valid @RequestBody EmployeeRequest x,HttpServletRequest r){access.requireHrOrAdmin(r);requireChoice(x.status(),"ACTIVE","INACTIVE");requireChoice(x.role(),"ADMIN","HR","MANAGER","EMPLOYEE");Employee e=employees.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Employee not found"));String role=e.getRole();copy(e,x);if(!access.admin(r))e.setRole(role);return employees.save(e);}
    @PatchMapping("/employees/{id}/status") public Employee employeeStatus(@PathVariable Long id,@RequestParam @jakarta.validation.constraints.NotBlank String status,HttpServletRequest r){access.requireHrOrAdmin(r);requireChoice(status,"ACTIVE","INACTIVE");Employee e=employees.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Employee not found"));e.setStatus(status.toUpperCase(Locale.ROOT));return employees.save(e);}
    @DeleteMapping("/employees/{id}") public Employee deactivateEmployee(@PathVariable Long id,HttpServletRequest r){access.requireHrOrAdmin(r);Employee e=employees.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Employee not found"));e.setStatus("INACTIVE");return employees.save(e);}
    @PatchMapping("/employees/{id}/role") public Employee employeeRole(@PathVariable Long id,@RequestParam String role,HttpServletRequest r){access.requireAdmin(r);requireChoice(role,"ADMIN","HR","MANAGER","EMPLOYEE");Employee e=employees.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Employee not found"));e.setRole(role.toUpperCase(Locale.ROOT));return employees.save(e);}
    @PutMapping("/employees/me/profile") public Employee updateProfile(@Valid @RequestBody EmployeeProfileRequest x,HttpServletRequest r){Employee e=access.currentEmployee(r);e.setPhone(x.phone());e.setGender(x.gender());e.setJobTitle(x.jobTitle());e.setAddress(x.address());return employees.save(e);}

    @GetMapping("/departments") public List<Department> departments(HttpServletRequest r){access.userId(r);return departments.findAll();}
    @PostMapping("/departments") public Department createDepartment(@Valid @RequestBody DepartmentRequest x,HttpServletRequest r){access.requireHrOrAdmin(r);Department d=new Department();d.setName(x.name());d.setDescription(x.description());Department saved=departments.save(d);try{d.setTeamConnectChannelId(chatGroups.create("Department · "+d.getName(),access.userId(r)).getId());saved=departments.save(d);}catch(RuntimeException ignored){}return saved;}
    @PutMapping("/departments/{id}") public Department updateDepartment(@PathVariable Long id,@Valid @RequestBody DepartmentRequest x,HttpServletRequest r){access.requireHrOrAdmin(r);Department d=departments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Department not found"));d.setName(x.name());d.setDescription(x.description());return departments.save(d);}
    @DeleteMapping("/departments/{id}") public void deleteDepartment(@PathVariable Long id,HttpServletRequest r){access.requireAdmin(r);Department d=departments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Department not found"));departments.delete(d);}
    @PostMapping("/departments/{id}/members/{employeeId}") public Object addDepartmentMember(@PathVariable Long id,@PathVariable Long employeeId,HttpServletRequest r){access.requireHrOrAdmin(r);Department d=departments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Department not found"));Employee e=employees.findById(employeeId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Employee not found"));if(d.getTeamConnectChannelId()==null||e.getTeamConnectUserId()==null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Department channel or TeamConnect user mapping is missing");chatGroups.addMember(d.getTeamConnectChannelId(),e.getTeamConnectUserId());return Map.of("success",true,"channelId",d.getTeamConnectChannelId());}

    @GetMapping("/projects") public List<Project> projectList(HttpServletRequest r){access.userId(r);return projects.findAllByOrderByStartDateDesc();}
    @PostMapping("/projects") public Project createProject(@Valid @RequestBody ProjectRequest x,HttpServletRequest r){access.requireHrOrAdmin(r);requireChoice(x.status(),"ACTIVE","PLANNED","COMPLETED","ON_HOLD");Project p=projects.save(projectFrom(x));try{p.setTeamConnectChannelId(chatGroups.create("Project · "+p.getProjectName(),access.userId(r)).getId());return projects.save(p);}catch(RuntimeException ignored){return p;}}
    @PutMapping("/projects/{id}") public Project updateProject(@PathVariable Long id,@Valid @RequestBody ProjectRequest x,HttpServletRequest r){access.requireHrOrAdmin(r);requireChoice(x.status(),"ACTIVE","PLANNED","COMPLETED","ON_HOLD");Project p=projects.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Project not found"));p.setProjectName(x.projectName());p.setDescription(x.description());p.setStartDate(x.startDate());p.setEndDate(x.endDate());p.setStatus(x.status());return projects.save(p);}
    @DeleteMapping("/projects/{id}") public void deleteProject(@PathVariable Long id,HttpServletRequest r){access.requireHrOrAdmin(r);Project p=projects.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Project not found"));projects.delete(p);}
    @PostMapping("/projects/{id}/members/{employeeId}") public Object addMember(@PathVariable Long id,@PathVariable Long employeeId,HttpServletRequest r){access.requireHrOrAdmin(r);if(!projects.existsById(id)||!employees.existsById(employeeId))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Project or employee not found");return members.save(new ProjectMember(id,employeeId));}
    @DeleteMapping("/projects/{id}/members/{employeeId}") public void removeMember(@PathVariable Long id,@PathVariable Long employeeId,HttpServletRequest r){access.requireHrOrAdmin(r);members.deleteById(new ProjectMember.Id(id,employeeId));}
    @GetMapping("/projects/me") public List<Project> myProjects(HttpServletRequest r){Long id=access.currentEmployee(r).getId();return members.findByIdEmployeeId(id).stream().map(x->projects.findById(x.getId().getProjectId()).orElse(null)).filter(Objects::nonNull).toList();}
    @GetMapping("/agents/projects/{id}/brief") public Map<String,String> projectBrief(@PathVariable Long id,HttpServletRequest r){Employee employee=access.currentEmployee(r);if(!access.admin(r)&&!access.hasRole(employee,"HR")&&members.findByIdProjectId(id).stream().noneMatch(member->Objects.equals(member.getId().getEmployeeId(),employee.getId())))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You are not assigned to this project.");if(!projects.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Project not found.");return Map.of("brief",agents.projectStatusBrief(id));}
    @GetMapping("/agents/data-quality") public List<EmsAgentService.DataQualityFinding> dataQuality(HttpServletRequest r){access.requireHrOrAdmin(r);return agents.dataQualityFindings();}

    @GetMapping("/attendance/me") public List<Attendance> myAttendance(HttpServletRequest r){requireFeature("ATTENDANCE_ENABLED");return attendance.findByEmployeeIdOrderByDateDesc(access.currentEmployee(r).getId());}
    @GetMapping("/attendance") public List<Attendance> allAttendance(HttpServletRequest r){access.requireHrOrAdmin(r);requireFeature("ATTENDANCE_ENABLED");return attendance.findAll();}
    @PostMapping("/attendance") public Attendance saveAttendance(@Valid @RequestBody AttendanceRequest x,HttpServletRequest r){access.requireHrOrAdmin(r);requireFeature("ATTENDANCE_ENABLED");requireChoice(x.status(),"PRESENT","ABSENT","LEAVE");Attendance a=attendance.findByEmployeeIdAndDate(x.employeeId(),x.date()).orElseGet(Attendance::new);a.setEmployeeId(x.employeeId());a.setDate(x.date());a.setStatus(x.status().toUpperCase(Locale.ROOT));a.setCheckIn(x.checkIn());a.setCheckOut(x.checkOut());a.setNotes(x.notes());return attendance.save(a);}
    @GetMapping("/agents/attendance/anomalies") public List<EmsAgentService.AttendanceAnomaly> attendanceAnomalies(HttpServletRequest r){access.requireHrOrAdmin(r);return agents.attendanceAnomalies(LocalDate.now());}

    @GetMapping("/leave/me") public List<LeaveRequest> myLeave(HttpServletRequest r){requireFeature("LEAVE_MANAGEMENT_ENABLED");return leaves.findByEmployeeIdOrderByAppliedOnDesc(access.currentEmployee(r).getId());}
    @GetMapping("/leave") public List<LeaveRequest> allLeave(HttpServletRequest r){access.requireHrOrAdmin(r);requireFeature("LEAVE_MANAGEMENT_ENABLED");return leaves.findAllByOrderByAppliedOnDesc();}
    @PostMapping("/leave") public LeaveRequest applyLeave(@Valid @RequestBody LeaveRequestDto x,HttpServletRequest r){requireFeature("LEAVE_MANAGEMENT_ENABLED");Employee e=access.currentEmployee(r);if(x.endDate().isBefore(x.startDate()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"End date must be after start date");LeaveRequest l=new LeaveRequest();l.setEmployeeId(e.getId());l.setStartDate(x.startDate());l.setEndDate(x.endDate());l.setLeaveType(x.leaveType());l.setReason(x.reason());LeaveRequest saved=leaves.save(l);notifications.notifyUser(e.getTeamConnectUserId(),"Leave request submitted","Your leave request was submitted for review.");var triage=agents.triageLeave(saved.getId());String triageMessage="AI leave triage recommendation: "+triage.recommendation()+". "+String.join(" ",triage.reasons());employees.findAllByOrderByNameAsc().stream().filter(hr->"HR".equalsIgnoreCase(hr.getRole())).forEach(hr->{if(hr.getTeamConnectUserId()!=null)notifications.notifyUser(hr.getTeamConnectUserId(),"Leave request triage",e.getName()+": "+triageMessage);});return saved;}
    @GetMapping("/agents/leave-triage/{id}") public EmsAgentService.LeaveTriage leaveTriage(@PathVariable Long id,HttpServletRequest r){access.requireHrOrAdmin(r);if(!leaves.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Leave request not found.");return agents.triageLeave(id);}
    @PatchMapping("/leave/{id}/status") public LeaveRequest leaveStatus(@PathVariable Long id,@RequestParam String status,HttpServletRequest r){access.requireHrOrAdmin(r);requireFeature("LEAVE_MANAGEMENT_ENABLED");requireChoice(status,"APPROVED","REJECTED");LeaveRequest l=leaves.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Leave request not found"));if(!"PENDING".equalsIgnoreCase(l.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Only pending leave requests can be reviewed.");l.setStatus(status.toUpperCase(Locale.ROOT));l.setReviewedBy(access.userId(r));LeaveRequest saved=leaves.save(l);employees.findById(l.getEmployeeId()).ifPresent(e->{notifications.notifyUser(e.getTeamConnectUserId(),"Leave request updated","Your leave request is now " + l.getStatus() + ".");notifications.email(e.getEmail(),"Leave request updated","Your leave request is now " + l.getStatus() + ".");});return saved;}

    @GetMapping("/payroll/me") public List<SalaryRecord> myPayroll(HttpServletRequest r){requireFeature("PAYROLL_ENABLED");return payroll.findByEmployeeIdOrderByPaymentDateDesc(access.currentEmployee(r).getId());}
    @GetMapping("/payroll") public List<SalaryRecord> allPayroll(HttpServletRequest r){access.requireHrOrAdmin(r);requireFeature("PAYROLL_ENABLED");return payroll.findAll();}
    @GetMapping("/payroll/{employeeId}") public List<SalaryRecord> employeePayroll(@PathVariable Long employeeId,HttpServletRequest r){access.requireHrOrAdmin(r);requireFeature("PAYROLL_ENABLED");return payroll.findByEmployeeIdOrderByPaymentDateDesc(employeeId);}
    @PostMapping("/agents/payroll/precheck") public EmsAgentService.PayrollPrecheck payrollPrecheck(@Valid @RequestBody PayrollRequest x,HttpServletRequest r){access.requireHrOrAdmin(r);requireFeature("PAYROLL_ENABLED");return agents.precheckPayroll(x);}
    @PostMapping("/payroll") public SalaryRecord createPayroll(@Valid @RequestBody PayrollRequest x,HttpServletRequest r){access.requireHrOrAdmin(r);requireFeature("PAYROLL_ENABLED");requireChoice(x.status(),"PROCESSED","PENDING");BigDecimal base=x.baseSalary(),bonus=x.bonus(),deductions=x.deductions(),net;if(base!=null||bonus!=null||deductions!=null){base=base==null?BigDecimal.ZERO:base;bonus=bonus==null?BigDecimal.ZERO:bonus;deductions=deductions==null?BigDecimal.ZERO:deductions;net=base.add(bonus).subtract(deductions);if(net.signum()<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Deductions cannot exceed base salary and bonus.");}else{if(x.amount()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Enter salary components or a net amount.");base=x.amount();bonus=BigDecimal.ZERO;deductions=BigDecimal.ZERO;net=x.amount();}SalaryRecord s=new SalaryRecord();s.setEmployeeId(x.employeeId());s.setAmount(net);s.setBaseSalary(base);s.setBonus(bonus);s.setDeductions(deductions);s.setPaymentDate(x.paymentDate());s.setPeriodLabel(x.periodLabel());s.setStatus(x.status());s.setNotes(x.notes());SalaryRecord saved=payroll.save(s);employees.findById(x.employeeId()).ifPresent(e->{notifications.notifyUser(e.getTeamConnectUserId(),"Payroll processed","A payroll record was processed for " + x.periodLabel());notifications.email(e.getEmail(),"Payroll processed","A payroll record was processed for " + x.periodLabel());});return saved;}

    @GetMapping("/performance/me") public List<PerformanceReview> myReviews(HttpServletRequest r){return reviews.findByEmployeeIdOrderByReviewDateDesc(access.currentEmployee(r).getId());}
    @GetMapping("/performance") public List<PerformanceReview> allReviews(HttpServletRequest r){access.requireHrOrAdmin(r);return reviews.findAll();}
    @PostMapping("/performance") public PerformanceReview createReview(@Valid @RequestBody PerformanceRequest x,HttpServletRequest r){access.requireHrOrAdmin(r);requireChoice(x.status(),"PUBLISHED","DRAFT");PerformanceReview p=new PerformanceReview();p.setEmployeeId(x.employeeId());p.setReviewerEmployeeId(x.reviewerEmployeeId());p.setRating(x.rating());p.setReviewContent(x.reviewContent());p.setReviewDate(x.reviewDate());p.setStatus(x.status());PerformanceReview saved=reviews.save(p);employees.findById(x.employeeId()).ifPresent(e->notifications.notifyUser(e.getTeamConnectUserId(),"Performance review created","A new performance review is available in TeamConnect."));return saved;}

    @GetMapping("/documents/me") public List<EmployeeDocument> myDocuments(HttpServletRequest r){return documents.findByEmployeeIdOrderByUploadedAtDesc(access.currentEmployee(r).getId());}
    @GetMapping("/documents") public List<EmployeeDocument> allDocuments(HttpServletRequest r){access.requireHrOrAdmin(r);return documents.findAllByOrderByUploadedAtDesc();}
    @GetMapping("/agents/onboarding") public List<EmsAgentService.OnboardingChecklist> onboardingChecklist(HttpServletRequest r){access.requireHrOrAdmin(r);return agents.onboardingChecklist();}
    @PostMapping("/agents/self-service") public Map<String,String> selfService(@RequestBody Map<String,String> x,HttpServletRequest r){Employee employee=access.currentEmployee(r);String question=x.get("question");if(question==null||question.isBlank()||question.length()>2000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Provide a question of at most 2,000 characters.");return Map.of("answer",agents.selfServiceAnswer(employee,question));}
    @PostMapping(value="/documents",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public EmployeeDocument upload(@RequestParam("employeeId") Long employeeId,@RequestParam("file") MultipartFile file,HttpServletRequest r)throws IOException{access.requireEmployee(r,employeeId);if(file==null||file.isEmpty()||file.getSize()>20_000_000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"File is empty or exceeds 20 MB");Path root=Path.of(fileDirectory).toAbsolutePath().normalize();Files.createDirectories(root);String key=UUID.randomUUID().toString();Files.copy(file.getInputStream(),root.resolve(key),StandardCopyOption.REPLACE_EXISTING);EmployeeDocument d=new EmployeeDocument();d.setEmployeeId(employeeId);d.setOriginalName(Optional.ofNullable(file.getOriginalFilename()).orElse("document").replaceAll("[\\\"\\r\\n]","_"));d.setStorageKey(key);d.setContentType(Optional.ofNullable(file.getContentType()).orElse("application/octet-stream"));d.setFileSize(file.getSize());d.setUploadedBy(access.userId(r));EmployeeDocument saved=documents.save(d);employees.findById(employeeId).ifPresent(e->notifications.notifyUser(e.getTeamConnectUserId(),"Document uploaded","A document was uploaded to your employee profile."));return saved;}
    @GetMapping("/documents/{id}/download") public ResponseEntity<InputStreamResource> download(@PathVariable Long id,HttpServletRequest r)throws IOException{EmployeeDocument d=documents.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Document not found"));access.requireEmployee(r,d.getEmployeeId());Path root=Path.of(fileDirectory).toAbsolutePath().normalize();Path p=root.resolve(d.getStorageKey()).normalize();if(!p.startsWith(root)||!Files.exists(p))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Document file not found");return ResponseEntity.ok().contentType(MediaType.parseMediaType(d.getContentType())).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+d.getOriginalName().replaceAll("[\\\"\\r\\n]","_")+"\"").body(new InputStreamResource(Files.newInputStream(p)));}

    @GetMapping("/announcements") public List<Announcement> announcementList(HttpServletRequest r){if(access.admin(r))return announcements.findTop30ByOrderByPublishedAtDesc();Employee e=access.currentEmployee(r);return announcements.findTop30ByOrderByPublishedAtDesc().stream().filter(a->"ALL".equalsIgnoreCase(a.getAudience())||("HR".equalsIgnoreCase(a.getAudience())&&"HR".equalsIgnoreCase(e.getRole()))||("MANAGERS".equalsIgnoreCase(a.getAudience())&&"MANAGER".equalsIgnoreCase(e.getRole()))).toList();}
    @PostMapping("/agents/announcement-draft") public EmsAgentService.AnnouncementDraft announcementDraft(@RequestBody Map<String,String> x,HttpServletRequest r){access.requireHrOrAdmin(r);String request=x.get("request");if(request==null||request.isBlank()||request.length()>4000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Provide an announcement request of at most 4,000 characters.");return agents.draftAnnouncement(request.trim());}
    @PostMapping("/agents/policy-question") public Map<String,String> policyQuestion(@RequestBody Map<String,String> x,HttpServletRequest r){access.userId(r);String question=x.get("question");if(question==null||question.isBlank()||question.length()>2000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Provide a question of at most 2,000 characters.");return Map.of("answer",workspaceAgents.answerPolicyQuestion(question));}
    @GetMapping("/agents/policies") public List<Map<String,Object>> policies(HttpServletRequest r){access.requireHrOrAdmin(r);return workspaceAgents.policies();}
    @PostMapping("/agents/policies") public Map<String,Object> addPolicy(@RequestBody Map<String,String> x,HttpServletRequest r){access.requireAdmin(r);String title=x.get("title"),content=x.get("content"),source=x.get("source");if(title==null||title.isBlank()||title.length()>180||content==null||content.isBlank()||content.length()>100000||(source!=null&&source.length()>255))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Policy title, source, or content is invalid.");return workspaceAgents.savePolicy(access.userId(r),title,content,source);}
    @PatchMapping("/agents/policies/{id}") public Map<String,Object> setPolicy(@PathVariable Long id,@RequestParam boolean active,HttpServletRequest r){access.requireAdmin(r);if(!workspaceAgents.setPolicyActive(id,active))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Policy document not found.");return Map.of("success",true,"active",active);}
    @PostMapping("/agents/performance-draft/{employeeId}") public Map<String,String> performanceDraft(@PathVariable Long employeeId,HttpServletRequest r){access.requireHrOrAdmin(r);if(!employees.existsById(employeeId))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Employee not found.");return Map.of("draft",agents.draftPerformanceComments(employeeId));}
    @GetMapping("/agents/payment-reconciliation") public Object paymentReconciliation(HttpServletRequest r){access.requireHrOrAdmin(r);return agents.reconciliationStatus().active()?agents.reconcileNow():agents.reconciliationStatus();}
    @PostMapping("/announcements") public Announcement announce(@Valid @RequestBody AnnouncementRequest x,HttpServletRequest r){access.requireAdmin(r);requireChoice(x.audience(),"ALL","HR","MANAGERS");Announcement a=new Announcement();a.setTitle(x.title());a.setBody(x.body());a.setAudience(x.audience().toUpperCase(Locale.ROOT));a.setCreatedBy(access.userId(r));Announcement saved=announcements.save(a);employees.findAll().stream().filter(e->"ALL".equalsIgnoreCase(a.getAudience())||("HR".equalsIgnoreCase(a.getAudience())&&"HR".equalsIgnoreCase(e.getRole()))||("MANAGERS".equalsIgnoreCase(a.getAudience())&&"MANAGER".equalsIgnoreCase(e.getRole()))).forEach(e->notifications.notifyUser(e.getTeamConnectUserId(),x.title(),x.body()));return saved;}
    @GetMapping("/reports/summary") public Map<String,Object> report(HttpServletRequest r){access.requireHrOrAdmin(r);List<Employee> all=employees.findAllByOrderByNameAsc();List<BigDecimal> salaries=all.stream().map(Employee::getSalary).filter(Objects::nonNull).toList();Map<String,Object> summary=new LinkedHashMap<>();summary.put("employees",all.size());summary.put("activeEmployees",all.stream().filter(e->"ACTIVE".equalsIgnoreCase(e.getStatus())).count());summary.put("departments",departments.count());summary.put("projects",projects.count());summary.put("leaveRequests",leaves.count());summary.put("attendanceRecords",attendance.count());summary.put("documents",documents.count());summary.put("performanceReviews",reviews.count());summary.put("averageSalary",salaries.stream().reduce(BigDecimal.ZERO,BigDecimal::add).divide(BigDecimal.valueOf(Math.max(salaries.size(),1)),2,java.math.RoundingMode.HALF_UP));summary.put("maximumSalary",salaries.stream().max(BigDecimal::compareTo).orElse(BigDecimal.ZERO));summary.put("minimumSalary",salaries.stream().min(BigDecimal::compareTo).orElse(BigDecimal.ZERO));summary.put("departmentCounts",departments.findAll().stream().map(d->Map.of("name",d.getName(),"employees",employees.countByDepartment_Id(d.getId()))).toList());summary.put("topPaidEmployees",all.stream().filter(e->e.getSalary()!=null).sorted(Comparator.comparing(Employee::getSalary).reversed()).limit(5).map(e->Map.of("name",e.getName(),"salary",e.getSalary(),"department",e.getDepartment()==null?"—":e.getDepartment().getName())).toList());return summary;}
    @GetMapping("/settings") public List<SystemSetting> settings(HttpServletRequest r){access.requireAdmin(r);return settings.findAll();}
    @PutMapping("/settings/{key}") public SystemSetting setting(@PathVariable String key,@RequestParam String value,HttpServletRequest r){access.requireAdmin(r);requireChoice(key,"ATTENDANCE_ENABLED","PAYROLL_ENABLED","LEAVE_MANAGEMENT_ENABLED","EMAIL_NOTIFICATIONS_ENABLED");requireChoice(value,"true","false");SystemSetting s=settings.findById(key).orElse(new SystemSetting(key,value));s.setValue(value.toLowerCase(Locale.ROOT));return settings.save(s);}

    private void requireFeature(String key){settings.findById(key).filter(s->"false".equalsIgnoreCase(s.getValue())).ifPresent(s->{throw new ResponseStatusException(HttpStatus.FORBIDDEN,"This module is currently disabled.");});}
    private void requireChoice(String value,String... choices){if(value==null||Arrays.stream(choices).noneMatch(x->x.equalsIgnoreCase(value)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported value.");}
    private Employee employeeFrom(EmployeeRequest x){Employee e=new Employee();copy(e,x);return e;} private void copy(Employee e,EmployeeRequest x){e.setEmsEmployeeId(x.emsEmployeeId());e.setTeamConnectUserId(x.teamConnectUserId());e.setName(x.name());e.setEmail(x.email());e.setPhone(x.phone());e.setGender(x.gender());e.setJobTitle(x.jobTitle());e.setHireDate(x.hireDate());e.setSalary(x.salary());e.setAddress(x.address());e.setRole(x.role().toUpperCase(Locale.ROOT));e.setStatus(x.status().toUpperCase(Locale.ROOT));e.setDepartment(x.departmentId()==null?null:departments.findById(x.departmentId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Department not found")));}
    private Project projectFrom(ProjectRequest x){Project p=new Project();p.setProjectName(x.projectName());p.setDescription(x.description());p.setStartDate(x.startDate());p.setEndDate(x.endDate());p.setStatus(x.status());return p;}
}
